// Distance as the hypotenuse of the coordinate-difference triangle.
// size(W,H) bounds the output under Asymptote's default keepAspect and does not scale labels,
// so the compiled box is a measurement rather than the declaration. The values below are what
// asy 2.87 actually produced; re-measure with `npm run content:figures --
// --record-aspect-ratios` if the toolchain changes.
size(271,241);
pair A=(0,0), B=(3,4), C=(3,0);
draw(A--C);
draw(C--B);
draw(A--B);
dot(A, black+2.5pt);
dot(C, black+2.5pt);
dot(B, black+2.5pt);
label("$A=(0,0)$",A,SW);
label("$B=(3,4)$",B,NE);
label("$C=(3,0)$",C,SE);
label("$3$",(1.5,0),S);
label("$4$",(3,2),E);
label("$d$",(1.5,2.2),NW);
label("only the differences of coordinates enter the formula",(1.5,-1.1),S);
